DROP PROCEDURE IF EXISTS `sp_record_uniform_payment`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_record_uniform_payment` (IN `p_sale_id` INT, IN `p_amount` DECIMAL(10,2), IN `p_method` VARCHAR(20), IN `p_reference` VARCHAR(100), IN `p_recorded_by` INT, IN `p_notes` TEXT)   BEGIN
  DECLARE v_total    DECIMAL(12,2);
  DECLARE v_paid     DECIMAL(12,2);
  DECLARE v_new_paid DECIMAL(12,2);
  DECLARE v_status   VARCHAR(20);

  SELECT total_amount, COALESCE(amount_paid, 0)
    INTO v_total, v_paid
  FROM uniform_sales WHERE id = p_sale_id FOR UPDATE;

  IF v_total IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Sale not found';
  END IF;

  IF p_amount <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Payment amount must be positive';
  END IF;

  SET v_new_paid = v_paid + p_amount;

  IF v_new_paid > v_total THEN
    SET v_new_paid = v_total;  
  END IF;

  IF v_new_paid >= v_total THEN
    SET v_status = 'paid';
  ELSEIF v_new_paid > 0 THEN
    SET v_status = 'partial';
  ELSE
    SET v_status = 'pending';
  END IF;

  UPDATE uniform_sales
    SET amount_paid = v_new_paid, payment_status = v_status
  WHERE id = p_sale_id;


  SELECT v_new_paid AS amount_paid, v_status AS payment_status,
         (v_total - v_new_paid) AS balance_due;
END$$

DROP PROCEDURE IF EXISTS `sp_refresh_student_payment_summary`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_refresh_student_payment_summary` (IN `p_student_id` INT, IN `p_year` INT, IN `p_term_id` INT)   BEGIN
    
        student_id, academic_year, term_id,
        total_paid, total_balance, last_payment_date
    )
    SELECT
        p_student_id,
        p_year,
        p_term_id,
        COALESCE(SUM(CASE WHEN status = 'confirmed' THEN amount_paid ELSE 0 END), 0),
        COALESCE((
            SELECT sfb.balance FROM student_fee_balances sfb
            WHERE sfb.student_id = p_student_id LIMIT 1
        ), 0),
        MAX(payment_date)
    FROM payment_transactions
    WHERE student_id = p_student_id
      AND term_id = p_term_id
      AND academic_year = p_year
    ON DUPLICATE KEY UPDATE
        total_paid = VALUES(total_paid),
        total_balance = VALUES(total_balance),
        last_payment_date = VALUES(last_payment_date),
        updated_at = NOW();
END$$

DROP PROCEDURE IF EXISTS `sp_register_uniform_sale`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_register_uniform_sale` (IN `p_student_id` INT, IN `p_item_id` INT, IN `p_size` VARCHAR(20), IN `p_quantity` INT, IN `p_unit_price` DECIMAL(10,2), IN `p_sold_by` INT, IN `p_notes` TEXT)   BEGIN
  DECLARE v_available INT DEFAULT 0;
  DECLARE v_total     DECIMAL(12,2);
  DECLARE v_receipt   VARCHAR(50);

  SELECT quantity_available INTO v_available
    FROM uniform_sizes WHERE item_id = p_item_id AND size = p_size FOR UPDATE;

  IF v_available < p_quantity THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Insufficient stock for the selected size';
  END IF;

  SET v_total = p_quantity * p_unit_price;
  SET v_receipt = CONCAT('RCP-', YEAR(CURDATE()), LPAD(MONTH(CURDATE()),2,'0'),
                         LPAD(DAY(CURDATE()),2,'0'), '-',
                         LPAD(FLOOR(RAND()*9999)+1, 4,'0'));

  
  UPDATE uniform_sizes
    SET quantity_available = quantity_available - p_quantity,
        quantity_sold      = quantity_sold + p_quantity,
        updated_at         = NOW()
  WHERE item_id = p_item_id AND size = p_size;

  
  UPDATE inventory_items
    SET current_quantity = current_quantity - p_quantity,
        updated_at = NOW()
  WHERE id = p_item_id;

  
     amount_paid, payment_status, sale_date, receipt_no, sold_by, notes)
  VALUES
    (p_student_id, p_item_id, p_size, p_quantity, p_unit_price, v_total,
     0, 'pending', CURDATE(), v_receipt, p_sold_by, p_notes);

  SELECT LAST_INSERT_ID() AS sale_id, v_receipt AS receipt_no, v_total AS total_amount;
END$$

DROP PROCEDURE IF EXISTS `sp_reject_class_promotion`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_reject_class_promotion` (IN `p_batch_id` INT UNSIGNED, IN `p_class_id` INT UNSIGNED, IN `p_stream_id` INT UNSIGNED, IN `p_rejection_reason` TEXT, IN `p_reviewed_by` INT UNSIGNED)   BEGIN
DECLARE v_error_msg VARCHAR(255);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN GET DIAGNOSTICS CONDITION 1 v_error_msg = MESSAGE_TEXT;
SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = 'Class rejection failed';
END;

UPDATE student_promotions
SET promotion_status = 'rejected',
  rejection_reason = p_rejection_reason,
  approved_by = p_reviewed_by,
  approval_date = NOW()
WHERE batch_id = p_batch_id
  AND promoted_to_class_id = p_class_id
  AND promoted_to_stream_id = p_stream_id
  AND promotion_status = 'pending_approval';

UPDATE class_promotion_queue
SET approval_status = 'rejected',
  rejected_count = (
    SELECT COUNT(*)
    FROM student_promotions
    WHERE batch_id = p_batch_id
      AND promoted_to_class_id = p_class_id
      AND promoted_to_stream_id = p_stream_id
      AND promotion_status = 'rejected'
  ),
  notes = p_rejection_reason,
  reviewed_at = NOW()
WHERE batch_id = p_batch_id
  AND class_id = p_class_id
  AND stream_id = p_stream_id;
END$$

DROP PROCEDURE IF EXISTS `sp_reject_student_promotion`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_reject_student_promotion` (IN `p_promotion_id` INT UNSIGNED, IN `p_rejection_reason` TEXT, IN `p_reviewed_by` INT UNSIGNED)   BEGIN
DECLARE v_batch_id INT UNSIGNED;
DECLARE v_promoted_class_id INT UNSIGNED;
DECLARE v_promoted_stream_id INT UNSIGNED;
DECLARE v_error_msg VARCHAR(255);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN GET DIAGNOSTICS CONDITION 1 v_error_msg = MESSAGE_TEXT;
SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = 'Student rejection failed';
END;

SELECT batch_id,
  promoted_to_class_id,
  promoted_to_stream_id INTO v_batch_id,
  v_promoted_class_id,
  v_promoted_stream_id
FROM student_promotions
WHERE id = p_promotion_id;

UPDATE student_promotions
SET promotion_status = 'rejected',
  rejection_reason = p_rejection_reason,
  approved_by = p_reviewed_by,
  approval_date = NOW()
WHERE id = p_promotion_id;

UPDATE class_promotion_queue
SET rejected_count = (
    SELECT COUNT(*)
    FROM student_promotions
    WHERE batch_id = v_batch_id
      AND promoted_to_class_id = v_promoted_class_id
      AND promoted_to_stream_id = v_promoted_stream_id
      AND promotion_status = 'rejected'
  ),
  pending_count = (
    SELECT COUNT(*)
    FROM student_promotions
    WHERE batch_id = v_batch_id
      AND promoted_to_class_id = v_promoted_class_id
      AND promoted_to_stream_id = v_promoted_stream_id
      AND promotion_status = 'pending_approval'
  )
WHERE batch_id = v_batch_id
  AND class_id = v_promoted_class_id
  AND stream_id = v_promoted_stream_id;
END$$

DROP PROCEDURE IF EXISTS `sp_remove_custom_stream`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_remove_custom_stream` (IN `p_stream_id` INT UNSIGNED)   BEGIN
DECLARE v_class_id INT UNSIGNED;
DECLARE v_stream_name VARCHAR(50);
DECLARE v_class_name VARCHAR(50);
DECLARE v_remaining_custom_streams INT;
DECLARE v_error_msg VARCHAR(255);
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN GET DIAGNOSTICS CONDITION 1 v_error_msg = MESSAGE_TEXT;
SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = v_error_msg;
END;

SELECT cs.class_id,
  cs.stream_name INTO v_class_id,
  v_stream_name
FROM class_streams cs
WHERE cs.id = p_stream_id;
IF v_class_id IS NULL THEN SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = 'Stream not found';
END IF;

SELECT c.name INTO v_class_name
FROM classes c
WHERE c.id = v_class_id;
IF v_stream_name = v_class_name THEN SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = 'Cannot delete default stream. Deactivate custom streams instead.';
END IF;

UPDATE class_streams
SET status = 'inactive'
WHERE id = p_stream_id;

SELECT COUNT(*) INTO v_remaining_custom_streams
FROM class_streams cs
WHERE cs.class_id = v_class_id
  AND cs.status = 'active'
  AND cs.stream_name != v_class_name;


IF v_remaining_custom_streams = 0 THEN
UPDATE class_streams
SET status = 'active'
WHERE class_id = v_class_id
  AND stream_name = v_class_name;
END IF;
END$$

