-- Table structure for table `formative_scores`
--
-- Creation: Apr 17, 2026 at 10:56 AM
--

DROP TABLE IF EXISTS `formative_scores`;
CREATE TABLE IF NOT EXISTS `formative_scores` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `assessment_id` int(10) UNSIGNED NOT NULL COMMENT 'FK → assessments.id',
  `student_id` int(10) UNSIGNED NOT NULL,
  `score` decimal(6,2) NOT NULL DEFAULT 0.00,
  `max_score` decimal(6,2) NOT NULL DEFAULT 100.00,
  `percentage` decimal(5,2) GENERATED ALWAYS AS (round(`score` / nullif(`max_score`,0) * 100,2)) STORED,
  `cbc_grade` enum('EE','ME','AE','BE') GENERATED ALWAYS AS (case when `score` / nullif(`max_score`,0) * 100 >= 75 then 'EE' when `score` / nullif(`max_score`,0) * 100 >= 60 then 'ME' when `score` / nullif(`max_score`,0) * 100 >= 40 then 'AE' else 'BE' end) STORED,
  `remarks` varchar(255) DEFAULT NULL,
  `entered_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_formative_score` (`assessment_id`,`student_id`),
  KEY `idx_fs_student` (`student_id`),
  KEY `idx_fs_assessment` (`assessment_id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

