  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `fund_id` int(10) UNSIGNED NOT NULL DEFAULT 1,
  `type` enum('expense','top_up','reconciliation_adjustment') NOT NULL,
  `category_id` int(10) UNSIGNED DEFAULT NULL,
  `description` varchar(500) NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `balance_after` decimal(15,2) NOT NULL COMMENT 'Running balance snapshot',
  `transaction_date` date NOT NULL,
  `receipt_number` varchar(100) DEFAULT NULL,
  `vendor_name` varchar(255) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `recorded_by` int(10) UNSIGNED NOT NULL,
  `approved_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_pct_fund` (`fund_id`),
  KEY `idx_pct_date` (`transaction_date`),
  KEY `idx_pct_type` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- RELATIONSHIPS FOR TABLE `petty_cash_transactions`:
--

--
-- Truncate table before insert `petty_cash_transactions`
--

TRUNCATE TABLE `petty_cash_transactions`;
--
-- Triggers `petty_cash_transactions`
--
DROP TRIGGER IF EXISTS `trg_petty_cash_balance_update`;
DELIMITER $$
CREATE TRIGGER `trg_petty_cash_balance_update` AFTER INSERT ON `petty_cash_transactions` FOR EACH ROW BEGIN
  IF NEW.type = 'expense' THEN
    UPDATE petty_cash_funds
       SET current_balance = current_balance - NEW.amount,
           updated_at = NOW()
     WHERE id = NEW.fund_id;
  ELSEIF NEW.type = 'top_up' THEN
    UPDATE petty_cash_funds
       SET current_balance = current_balance + NEW.amount,
           updated_at = NOW()
     WHERE id = NEW.fund_id;
  END IF;
END
$$
DELIMITER ;

