-- Triggers `role_delegations`
--
DROP TRIGGER IF EXISTS `trg_role_delegations_prevent_insert`;
DELIMITER $$
CREATE TRIGGER `trg_role_delegations_prevent_insert` BEFORE INSERT ON `role_delegations` FOR EACH ROW BEGIN
    IF NEW.active = 1 THEN
        VALUES (NEW.delegator_role_id, NEW.delegate_role_id, NEW.active, 'insert_blocked');
        SET NEW.active = 0; 
    END IF;
END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `trg_role_delegations_prevent_update`;
DELIMITER $$
CREATE TRIGGER `trg_role_delegations_prevent_update` BEFORE UPDATE ON `role_delegations` FOR EACH ROW BEGIN
    IF NEW.active = 1 AND OLD.active = 0 THEN
        VALUES (NEW.delegator_role_id, NEW.delegate_role_id, NEW.active, 'update_blocked');
        SET NEW.active = 0;
    END IF;
END
$$
DELIMITER ;

