--
-- Triggers `teaching_materials`
--
DROP TRIGGER IF EXISTS `trg_log_material_approval`;
DELIMITER $$
CREATE TRIGGER `trg_log_material_approval` AFTER UPDATE ON `teaching_materials` FOR EACH ROW BEGIN
    IF OLD.status != NEW.status THEN
        VALUES (
            'teaching_materials',
            NEW.id,
            'STATUS_CHANGE',
            OLD.status,
            NEW.status,
            NEW.teacher_id,
            NOW()
        );
    END IF;
END
$$
DELIMITER ;

