INSERT IGNORE INTO `job_vacancies` (`id`, `title`, `department`, `job_type`, `location`, `description`, `requirements`, `responsibilities`, `deadline`, `color`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Class Teacher — Grade 4', 'Teaching', 'Full-Time', 'Londiani Campus', 'We are looking for a dedicated and passionate Grade 4 class teacher with strong CBC implementation skills. The ideal candidate is a patient, creative educator who builds strong relationships with learners and parents, and who can lead a class of 35–40 pupils through the CBC Lower Primary curriculum.', '[\"P1 or B.Ed (Primary Education)\",\"TSC Registration (mandatory)\",\"Minimum 2 years teaching experience\",\"Strong CBC knowledge and implementation skills\",\"Experience with CBC portfolio management preferred\"]', '[\"Deliver engaging CBC-aligned lessons across all learning areas\",\"Maintain up-to-date class registers, portfolios, and assessment records\",\"Communicate regularly with parents on learner progress\",\"Participate in lesson plan reviews and peer observations\",\"Supervise learners during games, meals, and preps\"]', '2026-05-27', '#198754', 'open', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(2, 'Mathematics & Science Teacher (Grade 7–9)', 'Teaching', 'Full-Time', 'Londiani Campus', 'Seeking an experienced Junior Secondary Mathematics and Integrated Science teacher to prepare Grade 7–9 students for the KJSEA. The successful candidate will deliver high-quality lessons, set and mark SBA tasks, and provide targeted revision for national assessment candidates.', '[\"B.Ed (Science/Mathematics) or equivalent\",\"TSC Registration\",\"At least 3 years JSS teaching experience\",\"Deep knowledge of CBC Junior Secondary curriculum\",\"Experience with KJSEA preparation\"]', '[\"Teach Mathematics and Integrated Science to Grade 7, 8 and 9\",\"Design and administer SBA formative and summative assessments\",\"Provide KJSEA targeted revision and exam practice\",\"Mentor Grade 9 students on KJSEA pathway selection\",\"Maintain detailed learner progress records\"]', '2026-05-22', '#1976d2', 'open', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(3, 'School Nurse (Residential)', 'Health & Welfare', 'Full-Time', 'Londiani Campus', 'Qualified nurse to manage the school sick bay, maintain student health records, administer first aid, and coordinate with medical facilities for student welfare. This is a residential position with on-campus accommodation provided. Boarding school or institutional nursing experience is a strong advantage.', '[\"Diploma or Degree in Nursing\",\"Kenya Nursing Council (KNC) registration\",\"Valid First Aid and BLS certification\",\"Experience in school, paediatric or institutional health setting\",\"Able and willing to reside on campus\"]', '[\"Manage the school sick bay and student health records\",\"Administer first aid and basic medication as prescribed\",\"Coordinate referrals to hospitals and clinics\",\"Maintain vaccination and medical history records\",\"Provide health education sessions for students and staff\",\"Respond to health emergencies 24/7 (residential role)\"]', '2026-05-17', '#e91e63', 'open', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(4, 'ICT Technician & Lab Manager', 'Technology', 'Full-Time', 'Londiani Campus', 'We are seeking a skilled ICT Technician to manage our newly-commissioned 40-station computer laboratory, maintain network infrastructure, and support teachers in integrating technology into CBC lessons.', '[\"Diploma or Degree in ICT, Computer Science or related field\",\"Networking and hardware maintenance skills\",\"Experience with Windows OS, Office 365 or Google Workspace\",\"Ability to train staff and students in digital tools\",\"Strong problem-solving and communication skills\"]', '[\"Manage and maintain the computer lab (40 workstations)\",\"Administer school network, internet, and server infrastructure\",\"Support teachers in integrating EdTech tools into CBC lessons\",\"Train staff on school systems and digital tools\",\"Manage ICT inventory, warranties, and support contracts\"]', '2026-06-01', '#ff9800', 'open', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(5, 'Accounts Clerk', 'Finance & Administration', 'Full-Time', 'Londiani Campus', 'Support the school bursar in day-to-day fee collection, financial record-keeping, and accounting operations. The successful candidate should be detail-oriented with integrity, experience in school or institutional finance, and familiarity with accounting software.', '[\"CPA Part II or Diploma in Accounting\",\"At least 2 years accounting experience (school environment preferred)\",\"Proficiency in Excel and accounting software (QuickBooks/Sage)\",\"Experience with M-Pesa business collection\",\"High integrity and attention to detail\"]', '[\"Receive and record daily fee payments (cash and M-Pesa)\",\"Maintain fee collection registers and issue official receipts\",\"Follow up on outstanding fee balances with parents\",\"Prepare daily, weekly and monthly financial reports\",\"Assist bursar with bank reconciliations and audits\",\"Manage petty cash float and staff advance records\"]', '2026-05-25', '#00695c', 'open', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(6, 'Games Teacher & Sports Coach', 'Co-Curricular', 'Full-Time', 'Londiani Campus', 'Lead and grow the school\'s sports programs including football, athletics, netball, and basketball. Prepare students and teams for inter-schools competitions at sub-county, county, and national levels.', '[\"Diploma or Degree in Physical Education or Sports Science\",\"TSC Registration or KSCA coaching certificate\",\"Minimum 2 years coaching or PE teaching experience\",\"Proven track record in competitive school sports\",\"Strong motivational and disciplinary skills\"]', '[\"Teach Physical and Health Education to all CBC grade levels\",\"Coach school teams in football, athletics, netball and basketball\",\"Organise and manage inter-house sports events\",\"Prepare teams for inter-schools competitions\",\"Maintain sports equipment inventory and facilities\",\"Coordinate SBA physical assessment records\"]', '2026-05-12', '#9c27b0', 'open', '2026-04-27 06:13:56', '2026-04-27 06:13:56');
INSERT IGNORE INTO `leadership_team` (`id`, `name`, `title`, `bio`, `avatar_url`, `avatar_color`, `email`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'School Director', 'School Founder & Director', '20+ years in education leadership. Holds a Masters in Educational Management from University of Nairobi.', NULL, '#0d4f2a', NULL, 10, 1, '2026-04-27 06:18:19', '2026-04-27 06:18:19'),
(2, 'Head Teacher', 'Head Teacher', 'B.Ed (Hons), experienced in CBC implementation and school administration. Sets the academic tone for the school.', NULL, '#198754', NULL, 20, 1, '2026-04-27 06:18:19', '2026-04-27 06:18:19'),
(3, 'Deputy (Academic)', 'Deputy Head — Academic', 'Oversees curriculum delivery, lesson plans, timetabling, teacher development, and academic performance monitoring.', NULL, '#1976d2', NULL, 30, 1, '2026-04-27 06:18:19', '2026-04-27 06:18:19'),
(4, 'Deputy (Discipline)', 'Deputy Head — Discipline', 'Manages student conduct, welfare, community relations, and the boarding programme pastoral care.', NULL, '#7b1fa2', NULL, 40, 1, '2026-04-27 06:18:19', '2026-04-27 06:18:19'),
(5, 'The Bursar', 'School Bursar / Accountant', 'CPA-K certified. Manages school finances, fee collection, budgets, payroll, and financial reporting.', NULL, '#e65100', NULL, 50, 1, '2026-04-27 06:18:19', '2026-04-27 06:18:19'),
(6, 'Admissions Officer', 'Admissions Officer', 'Handles student intake, placement assessments, records management, and parent liaison throughout the admission process.', NULL, '#00695c', NULL, 60, 1, '2026-04-27 06:18:19', '2026-04-27 06:18:19');
