INSERT IGNORE INTO `learning_outcomes` (`id`, `learning_area_id`, `strand_id`, `sub_strand_id`, `outcome`, `grade_level`, `created_at`) VALUES
(20564, 84, 627, 2351, 'pick out the letters a-h and their corresponding sounds for effective communication', 'Grade 1', '2026-07-31 23:44:09'),
(20565, 84, 627, 2351, 'pronounce words with the sounds /a:/, /æ/, / ɜː/, /ɑː/, /ə/, /b:/, /b/, /k/, /s/, /d/, /e/, /iː/, /f/ /g/, /h/ for oral fluency', 'Grade 1', '2026-07-31 23:44:09'),
(20566, 84, 627, 2351, 'use words related to greetings in everyday conversations', 'Grade 1', '2026-07-31 23:44:09'),
(20567, 84, 627, 2351, 'appreciate the role of greetings in diverse contexts', 'Grade 1', '2026-07-31 23:44:09'),
(20568, 84, 627, 2351, 'identify words featuring the sounds /iː/, /ɪ / /aɪ/ /ʤ/, k as in /k/ /l/ /m/ /n/ /ɒ/ /ɔː/ and /p/ in varied contexts', 'Grade 1', '2026-07-31 23:44:09'),
(20569, 84, 627, 2351, 'articulate the sounds /iː/, /ɪ / /aɪ/ /ʤ/, k as in /k/ /l//m/ /n/ / ɒ/ /ɔː/ and /p/ for speaking fluency', 'Grade 1', '2026-07-31 23:44:09'),
(20570, 84, 627, 2351, 'make sentences using words related to the theme', 'Grade 1', '2026-07-31 23:44:09'),
(20571, 84, 627, 2351, 'value the role of listening in communication', 'Grade 1', '2026-07-31 23:44:09'),
(20572, 84, 627, 2351, 'link the letters q, r, s, t, u, v, w, x, y, z with their corresponding sounds', 'Grade 1', '2026-07-31 23:44:09'),
(20573, 84, 627, 2351, 'use words featuring the sounds /q/, /r/, /s/, / t /, /ʌ /, /v/, /w/, /x/, /y/ and /z/ in words for oral fluency', 'Grade 1', '2026-07-31 23:44:09'),
(20574, 84, 627, 2351, 'respond verbally and non- verbally to simple one- directional instructions', 'Grade 1', '2026-07-31 23:44:09'),
(20575, 84, 627, 2351, 'advocate for accurate pronunciation in oral conversations', 'Grade 1', '2026-07-31 23:44:09'),
(20576, 84, 627, 2351, 'as in cup, v, w, x, y, z as modelled, • work with peers to say the sounds /q/, /r/, /s/, t, //ʌ /, /v/, /w/, /x/, /y/ and /z /, • view a chart featuring the letters and say the corresponding sounds, • work jointly to repeat words with the target sounds from an oral text, • role play simple instructions with peers, • sing rhymes, say tongue twisters and poems featuring the target sounds. 1. How can we become better listeners?', 'Grade 1', '2026-07-31 23:44:09'),
(20577, 84, 627, 2351, 'articulate the sounds /æ/ /m/, /t/ /e/ for clarity in communication', 'Grade 1', '2026-07-31 23:44:09'),
