INSERT IGNORE INTO `roles` (`id`, `name`, `description`, `scope`, `is_system`, `is_active`, `user_count`, `created_at`, `updated_at`) VALUES
(2, 'System Administrator', '[ROOT/SUPER USER] Complete system access: codebase management, database management, system configuration, all permissions, full technical control. This is the developer/technical admin account.', 'system', 1, 1, 1, '2025-12-06 12:54:06', '2026-04-17 12:50:09'),
(3, 'Director', 'School Director - Financial reports viewing, approvals for transactions, fees structure updates, transport fees, payroll approvals, strategic decisions', 'school', 0, 1, 1, '2025-12-06 12:54:06', '2026-04-17 12:50:09'),
(4, 'School Administrator', 'School Administrator - Operational school admin: manages school users, roles & permissions, provides support to all staff, accesses most school operations (academic, students, staff, communications). Does NOT have codebase/database access.', 'school', 0, 1, 1, '2025-12-06 12:54:06', '2026-04-17 12:50:09'),
(5, 'Headteacher', 'Headteacher - Academic year scheduling, student admissions (with deputies), timetabling, academic oversight, parent communication, overall school management', 'school', 0, 1, 1, '2025-12-06 12:54:07', '2026-04-17 12:50:09'),
(6, 'Deputy Head - Academic', 'Deputy Headteacher (Academic) - Student admissions, student promotion, timetabling, academic oversight, parent communication', 'school', 0, 1, 1, '2025-12-06 12:54:07', '2026-04-17 12:50:09'),
(7, 'Class Teacher', 'Class Teacher - Class management, attendance, assessments, results, lesson plans, parent communication, timetabling review', 'school', 0, 1, 13, '2025-12-06 12:54:07', '2026-04-17 12:50:09'),
(8, 'Subject Teacher', 'Subject Teacher - Subject teaching, exams, assessments, results, lesson plans, timetabling review', 'school', 0, 1, 13, '2025-12-06 12:54:07', '2026-04-17 12:50:09'),
(9, 'Intern/Student Teacher', 'Intern/Student Teacher - Learning internship, lesson plan viewing, teaching observation, limited access', 'school', 0, 1, 1, '2025-12-06 12:54:07', '2026-04-17 12:50:09'),
(10, 'Accountant', 'Accountant - Complete financial management: fees, payroll, budgets, reconciliation, financial reports, P9/payslip generation, fee structure updates, transport fees, worker payments, account management for academic years', 'school', 0, 1, 1, '2025-12-06 12:54:07', '2026-04-17 12:50:09'),
(14, 'Inventory Manager', 'Inventory Manager - School uniforms store management, uniform inventory, requisitions, stock control', 'school', 0, 1, 1, '2025-12-06 12:54:07', '2026-04-17 12:50:09'),
(16, 'Cateress', 'Cateress - Kitchen management: all kitchen staff coordination (chefs, cooks), meal planning, food store management, inventory for kitchen supplies', 'school', 0, 1, 1, '2025-12-06 12:54:07', '2026-04-17 12:50:09'),
(18, 'Boarding Master', 'Boarding Master - Boarding facility management, student welfare in boarding, health monitoring, boarding discipline', 'school', 0, 1, 1, '2025-12-06 12:54:07', '2026-04-17 12:50:09'),
(21, 'Talent Development', 'Talent Development Manager - Games, sports, music, talent acquisition and development, student activities, competitions, performances', 'school', 0, 1, 1, '2025-12-06 12:54:07', '2026-04-17 12:50:09'),
