(4457, 44, 1, 92, 'Kiswahili', 92, 861, 3331, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora d/nd,ch/sh,j/nj na g/ng', 'Kusikiliza na Kuzungumza', 1, 'Kusikiliza na Kuzungumza', 'Matamshi Bora d/nd,ch/sh,j/nj na g/ng', 'kutambua silabi zinazotokana na sauti d/nd, ch/sh, j/nj na g/ng katika maneno\nkutamka silabi zinazotokana na sauti zinazokaribiana kimatamshi ili kuimarisha matamshi\nkutamka vitanzandimi vinavyoundwa kwa silabi za sauti zinazokaribiana kimatamshi ili kuimarisha matamshi bora\nkuchangamkia kukariri vitanzandimi vinavyoundwa kwa silabi za sauti zinazokaribiana kimatamshi ili kuimarisha matamshi', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4458, 44, 1, 92, 'Kiswahili', 92, 861, 3332, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Maamkuzi na Maagano', 'Kusikiliza na Kuzungumza', 2, 'Kusikiliza na Kuzungumza', 'Maamkuzi na Maagano', 'kujadili umuhimu wa maamkuzi na maagano katika mawasiliano\nkujadili maamkuzi na maagano yanayotumika katika miktadha mbalimbali\nkutumia aina mbalimbali za maamkuzi na maagano katika mawasiliano\nkuchangamkia maamkuzi na maagano katika mahusiano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50');
INSERT IGNORE INTO `schemes_of_work` (`id`, `teacher_id`, `class_id`, `subject_id`, `subject_name`, `learning_area_id`, `strand_id`, `sub_strand_id`, `coverage_id`, `academic_year_id`, `term_id`, `term_number`, `title`, `description`, `week_number`, `strand`, `sub_strand`, `learning_outcomes`, `key_vocabulary`, `resources`, `activities`, `assessment_methods`, `status`, `approved_by`, `approved_at`, `rejection_reason`, `file_path`, `created_at`, `updated_at`) VALUES
(4459, 44, 1, 92, 'Kiswahili', 92, 861, 3333, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora', 'Kusikiliza na Kuzungumza', 3, 'Kusikiliza na Kuzungumza', 'Matamshi Bora', 'kutambua vitendawili kwenye matini mbalimbali\nkutega na kutegua vitendawili ili kujenga matamshi bora\nkuchangamkia matumizi ya vitendawili katika mawasiliano\nkukariri au kuimba shairi kuhusu suala lengwa kwa kuzingatia, matamshi ya maneno yenye sauti lengwa na mahadhi mbalimbali ili kukuza matamshi bora\nkueleza maana ya maneno yenye sauti lengwa yaliyotumika katika shairi\nkutumia kwa usahihi msamiati uliotumiwa katika shairi ili kuboresha mawasiliano\nkuonyesha ufahamu wa ujumbe katika shairi kwa kujibu maswali\nkuchangamkia mahadhi mbalimbali katika ushairi', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4460, 44, 1, 92, 'Kiswahili', 92, 861, 3334, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Nahau', 'Kusikiliza na Kuzungumza', 4, 'Kusikiliza na Kuzungumza', 'Nahau', 'kutambua nahau za kazi na ushirikiano katika matini mbalimbali\nkujadili maana ya nahau mbalimbali za kazi na ushirikiano ili kuzitofautisha\nkutumia nahau za kazi na ushirikiano katika mawasiliano\nkuthamini matumizi ya nahau za kazi na ushirikiano katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4461, 44, 1, 92, 'Kiswahili', 92, 861, 3335, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Visawe', 'Kusikiliza na Kuzungumza', 5, 'Kusikiliza na Kuzungumza', 'Visawe', 'kutambua maneno zaidi ya matatu yenye maana sawa katika kundi la maneno\nkutumia visawe ifaavyo katika mawasiliano\nkuthamini matumizi ya maneno zaidi ya matatu yenye maana sawa katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4462, 44, 1, 92, 'Kiswahili', 92, 861, 3336, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Mazungumzo ya Kimuktadha', 'Kusikiliza na Kuzungumza', 6, 'Kusikiliza na Kuzungumza', 'Mazungumzo ya Kimuktadha', 'kutambua miktadha rasmi na isiyo rasmi katika mawasiliano ili kuitofautisha\nkutumia lugha katika miktadha rasmi na isiyo rasmi ili kufanikisha mawasiliano\nkuchangamkia matumizi ya lugha katika miktadha rasmi na isiyo rasmi kuimarisha maadili yafaayo', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4463, 44, 1, 92, 'Kiswahili', 92, 861, 3337, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Sitiari za Tabia', 'Kusikiliza na Kuzungumza', 7, 'Kusikiliza na Kuzungumza', 'Sitiari za Tabia', 'kujadili dhana ya sitiari ili kuitofautisha na dhana zingine za lugha\nkutambua sitiari za tabia katika matini mbalimbali ili kuzibainisha\nkutumia sitiari za tabia kwa usahihi katika sentensi ili kuimarisha mawasiliano\nkufurahia matumizi ya sitiari katika mawasiliano ya kila siku', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4464, 44, 1, 92, 'Kiswahili', 92, 861, 3338, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Kujieleza kwa Ufasaha', 'Kusikiliza na Kuzungumza', 8, 'Kusikiliza na Kuzungumza', 'Kujieleza kwa Ufasaha', 'kubuni na kusimulia kisa mbele ya wenzake akizingatia mada lengwa\nkutumia ishara zifaazo kuimarisha masimulizi yake\nkufurahia usimulizi wa visa mbalimbali kuhusu maisha', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4465, 44, 1, 92, 'Kiswahili', 92, 861, 3339, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Methali', 'Kusikiliza na Kuzungumza', 9, 'Kusikiliza na Kuzungumza', 'Methali', 'kutambua methali zinazohusu umoja na ushirikiano katika matini\nkueleza maana na matumizi ya methali mbalimbali zinazohusu umoja na ushirikiano katika jamii\nkutumia methali zinazohusu umoja na ushirikiano katika mawasiliano\nkuchangamkia matumizi ya methali zinazohimiza umoja na ushirikiano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4466, 44, 1, 92, 'Kiswahili', 92, 861, 3340, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Heshima, Adabu na Vyeo', 'Kusikiliza na Kuzungumza', 10, 'Kusikiliza na Kuzungumza', 'Heshima, Adabu na Vyeo', 'kutambua maneno ya heshima yanayotumiwa katika mawasiliano\nkuonyesha uelewa wa maneno ya heshima kwa kuyatumia kwa usahihi katika mawasiliano\nkuthamini kutumia maneno ya heshima katika mawasiliano ya kila siku', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4467, 44, 1, 92, 'Kiswahili', 92, 862, 3341, NULL, NULL, 8, NULL, 'Kiswahili: Kusoma - Kusoma kwa Ufahamu', 'Kusoma', 11, 'Kusoma', 'Kusoma kwa Ufahamu', 'kutambua msamiati wa suala lengwa uliotumika katika kifungu ili kuimarisha ufahamu\nkueleza maana ya msamiati lengwa ili kuubainisha\nkuonyesha ufahamu wa kifungu kwa kujibu maswali na kutoa muhtasari\nkuchangamkia usomaji ili kuimarisha ufahamu\nkujadili dhana za ukwapi na utao katika shairi ili kuzibainisha\nkutambua mashairi ya tathnia, tathlitha na tarbia kwa kuzingatia muundo\nkusoma mashairi ya tathnia, tathlitha na tarbia ili kupata ujumbe\nkuchangamkia usomaji wa mashairi ili kuyathamini\nkujadili sifa za mchezo wa kuigiza ili kuzibainisha\nkusoma mchezo mfupi wa kuigiza kwa ufasaha kwa kuzingatia ujumbe na msamiati wa suala lengwa\nkuonyesha ufahamu wa mchezo wa kuigiza kwa kujibu maswali na kutoa muhtasari\nkuonea fahari nafasi ya mchezo wa kuigiza katika jamii', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4468, 44, 1, 92, 'Kiswahili', 92, 862, 3342, NULL, NULL, 8, NULL, 'Kiswahili: Kusoma - Kusoma kwa Kina', 'Kusoma', 12, 'Kusoma', 'Kusoma kwa Kina', 'kutambua maana, tahajia, ngeli na aina za maneno kwa kutumia kamusi\nkutumia kamusi ipasavyo kutafuta maana za maneno mageni yaliyo katika matini aliyosoma ili kukuza msamiati wake\nkuchangamkia umuhimu wa kamusi katika kukuza msamiati na sarufi ya Kiswahili\nkujadili mambo ya kuzingatia katika kuchagua makala ya kusoma katika maktaba\nkutambua makala atakayosoma katika maktaba\nkusoma makala mbalimbali ili kupata ujumbe\nkufurahia kusoma makala mbalimbali ili kujenga ufasaha wa lugha', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4469, 44, 1, 92, 'Kiswahili', 92, 862, 3343, NULL, NULL, 8, NULL, 'Kiswahili: Kusoma - Kusoma kwa Ufasaha', 'Kusoma', 13, 'Kusoma', 'Kusoma kwa Ufasaha', 'kutambua vipengele vya kuzingatia katika kusoma kwa ufasaha\nkusoma kifungu kwa kuzingatia matamshi bora\nkusoma kifungu kwa kasi ifaayo\nkusoma kifungu kwa kutumia sauti ipasavyo\nkusoma kifungu kwa kuambatanisha ishara zifaazo\nkuchangamkia kusoma kifungu kwa kuzingatia vipengele vya usomaji\nkuchangamkia kusoma kifungu kwa kuzingatia vipengele vya usomaji kwa ufasaha', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4470, 44, 1, 92, 'Kiswahili', 92, 862, 3344, NULL, NULL, 8, NULL, 'Kiswahili: Kusoma - Kusoma kwa Mapana', 'Kusoma', 14, 'Kusoma', 'Kusoma kwa Mapana', 'kutambua hatua za kiusalama katika matumizi ya vifaa vya kidijitali anaposoma\nkusakura matini kwenye tovuti salama ili kupata vifungu vya kusoma vyenye mada lengwa\nkutumia vifaa ya kidijitali kwa urahisi ili kupata matini yanayolengwa\nkuchangamkia matumizi ya vifaa vya kidijitali katika kutafuta na kusoma ujumbe ili kuimarisha maarifa yake\nkutambua matini anazotaka kusoma kwenye maktaba\nkuchagua matini anazotaka kusoma kwenye maktaba\nkusoma matini ili kufaidika na ujumbe na lugha inayotumiwa\nkufurahia usomaji wa matini za aina mbalimbali ili kujenga utamaduni wa kusoma\nkutambua aina mbalimbali za matini ili kuchagua inayomvutia\nkusoma matini aliyochagua ili kufaidika na ujumbe na lugha iliyotumiwa\nkufurahia usomaji wa aina mbalimbali za matini ili kupanua mawazo yake\nkutambua na kufungua faili iliyo na kifungu cha kusoma ili kuimarisha umilisi wake wa kutumia tarakilishi\nkuonyesha uelewa wa hatua za kiusalama kwa kusakura matini kwenye tovuti salama ili kupata vifungu vya kusoma kutumia vyombo vya kidijitali', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4471, 44, 1, 92, 'Kiswahili', 92, 863, 3345, NULL, NULL, 8, NULL, 'Kiswahili: Kuandika - Insha ya Wasifu', 'Kuandika', 15, 'Kuandika', 'Insha ya Wasifu', 'kujadili maudhui ya insha ya wasifu kwa kuzingatia mada ili kukuza ubunifu\nkuandika insha ya wasifu kwa ubunifu ili kujenga maelezo yenye kutoa picha dhahiri\nkuchangamkia utunzi wa insha ya wasifu ili kujenga ubunifu\nkutambua vipengele vya kimuundo vya insha za wasifu ili kuibainisha\nkuandika insha ya wasifu kwa kuzingatia sifa zake\nkufurahia uandishi wa insha za wasifu kwa kueleza sifa za mtu, kitu, mnyama au mahali', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4472, 44, 1, 92, 'Kiswahili', 92, 863, 3346, NULL, NULL, 8, NULL, 'Kiswahili: Kuandika - Insha za Masimulizi', 'Kuandika', 16, 'Kuandika', 'Insha za Masimulizi', 'kubainisha vidokezo vya kutumia katika kuandika insha ya masimulizi\nkuandika insha ya masimulizi kwa kuzingatia mtindo na muundo wake\nkuchangamkia utunzi wa insha ya masimulizi ili kujenga ubunifu\nkujadili mtiririko wa hoja katika insha ya masimulizi\nkuandika insha ya masimulizi kwa kufuata kanuni zifaazo\nkuchangamkia utunzi mzuri katika uandishi wa insha ya masimulizi\nkueleza maudhui ya insha ya masimulizi ili kuandika ifaavyo\nkuchangamkia utunzi mzuri ili kuimarisha mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4473, 44, 1, 92, 'Kiswahili', 92, 863, 3347, NULL, NULL, 8, NULL, 'Kiswahili: Kuandika - Kuandika kwa Tarakilishi', 'Kuandika', 17, 'Kuandika', 'Kuandika kwa Tarakilishi', 'kutambua aina mbalimbali za maandishi ya tarakilishi na ishara zinazotumiwa katika maandishi ya tarakilishi\nkuandika kifungu kifupi kuhusu suala lengwa kwa kutumia maandishi mbalimbali yaliyotofautishwa katika tarakilishi\nufurahia utumiaji wa tarakilishi katika kuandika', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4474, 44, 1, 92, 'Kiswahili', 92, 863, 3348, NULL, NULL, 8, NULL, 'Kiswahili: Kuandika - Barua Rasmi', 'Kuandika', 18, 'Kuandika', 'Barua Rasmi', 'kutambua barua rasmi kwa kuzingatia muundo wake\nkutambua vipengele vya barua rasmi ili kuvizingatia katika uandishi\nkuandika barua rasmi kwa kufuata kanuni zifaazo\nkuchangamkia umuhimu wa barua rasmi katika mawasiliano\nkujadili maudhui ili kuandika barua rasmi inayozingatia mada\nkuandika barua rasmi inayozingatia mada, hati safi, muundo na mtindo ufaao ili kuwasiliana ipasavyo\nkuchangamkia utunzi wa barua rasmi katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4475, 44, 1, 92, 'Kiswahili', 92, 863, 3349, NULL, NULL, 8, NULL, 'Kiswahili: Kuandika - Insha za Maelezo', 'Kuandika', 19, 'Kuandika', 'Insha za Maelezo', 'kutambua insha za maelezo katika matini mbalimbali\nkuandika insha ya maelezo kwa kufuata kanuni zifaazo\nkuchangamkia utunzi bora maishani\nkujadili maudhui ya insha ya maelezo ili kukuza ubunifu\nkuandika insha ya maelezo kwa kuzingatia mada, mtiririko, sarufi, muundo na mtindo ufaao\nkuchangamkia utungaji wa insha za maelezo ili kukuza hali ya kujiamini\nkueleza maudhui ya insha ya maelezo kwa kuzingatia mada\nkuandika insha ya maelezo kwa kufuata kanuni zifaazo ili kufanikisha, mawasiliano\nkuchangamkia utunzi mzuri wenye mapambo ya lugha', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4476, 44, 1, 92, 'Kiswahili', 92, 864, 3350, NULL, NULL, 8, NULL, 'Kiswahili: Sarufi - Vivumishi vya Sifa', 'Sarufi', 20, 'Sarufi', 'Vivumishi vya Sifa', 'kueleza maana ya vivumishi vya sifa ili kuvitofautisha na aina zingine za maneno\nkutambua vivumishi vya sifa katika matini mbalimbali ili kuvibainisha\nkutumia vivumishi vya sifa kutunga sentensi au vifungu vya maneno kwa usahihi\nkufurahia kutumia vivumishi vya sifa katika sentensi au vifungu vya maneno', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4477, 44, 1, 92, 'Kiswahili', 92, 864, 3351, NULL, NULL, 8, NULL, 'Kiswahili: Sarufi - Vivumishi Viashiria', 'Sarufi', 21, 'Sarufi', 'Vivumishi Viashiria', 'kueleza maana ya vivumishi viashiria ipasavyo ili kuvibainisha\nkutambua vivumishi viashiria katika matini mbalimbali\nkutumia vivumishi viashiria katika sentensi au vifungu vya maneno kwa usahihi\nkufurahia kutumia vivumishi viashiria katika sentensi au vifungu vya maneno', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4478, 44, 1, 92, 'Kiswahili', 92, 864, 3352, NULL, NULL, 8, NULL, 'Kiswahili: Sarufi - Vivumishi Vimilikishi', 'Sarufi', 22, 'Sarufi', 'Vivumishi Vimilikishi', 'kuelezea maana ya vivumishi vimilikishi ili kuvitofautisha na aina zingine za vivumishi\nkutambua vivumishi vimilikishi katika matini mbalimbali\nkutumia vivumishi vimilikishi katika sentensi\nkuonea fahari matumizi ya vivumishi vimilikishi katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
