(4598, 44, 2, 85, 'Kiswahili', 85, 712, 2663, NULL, NULL, 8, NULL, 'Kiswahili: Kuandika - Nafasi ya Pambizo katika Uandishi', 'Kuandika', 9, 'Kuandika', 'Nafasi ya Pambizo katika Uandishi', 'kutambua nafasi ya pambizo na nafasi ya kuzingatia anapoandika aya\nkuandika kifungu cha maneno yasiyozidi 60 akizingatia pambizo na aya\nkufurahia kuandika kifungu akizingatia pambizo na aya', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4599, 44, 2, 85, 'Kiswahili', 85, 712, 2664, NULL, NULL, 8, NULL, 'Kiswahili: Kuandika - Matumizi ya Kiulizi', 'Kuandika', 10, 'Kuandika', 'Matumizi ya Kiulizi', 'kutambua alama ya kiulizi katika maandishi\nkueleza matumizi ya alama ya kiulizi katika maandishi\nkuandika kifungu cha maneno kati ya 55-60 akitumia alama ya kiulizi ipasavyo\nkufurahia kutumia kiulizi katika maandishi ili kufanikisha mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50'),
(4600, 44, 2, 85, 'Kiswahili', 85, 712, 2665, NULL, NULL, 8, NULL, 'Kiswahili: Kuandika - Imla', 'Kuandika', 11, 'Kuandika', 'Imla', 'kutambua maneno yanayotamkwa kwenye imla ili kuyaandika ipasavyo\nkuandika kifungu cha maneno 55-60 yanayotamkwa kwenye imla akizingatia kanuni za uandishi zifaazo\nkuchangamkia kuandika kifungu akitumia maneno yanayotamkwa kwa kuzingatia kanuni zifaazo za uandishi', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:50', '2026-08-01 00:02:50');
