(4685, 44, 2, 89, 'Religious Education', 89, 735, 2761, NULL, NULL, 8, NULL, 'Religious Education: Relationship - Care and dua for the sick (IRE)', 'Relationship', 34, 'Relationship', 'Care and dua for the sick', 'recite the dua for the sick for spiritual growth\nidentify ways of showing care for the sick to enhance brotherhood\nappreciate the importance of visiting the sick as an act of ibadah', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:51', '2026-08-01 00:02:51'),
(4686, 44, 2, 89, 'Religious Education', 89, 736, 2762, NULL, NULL, 8, NULL, 'Religious Education: Siirah - Early life of the Prophet (S.A.W.) (IRE)', 'Siirah', 35, 'Siirah', 'Early life of the Prophet (S.A.W.)', 'mention the activities that were carried out by the prophet (S.A.W.) during the early stages of his life\nidentify the qualities that can be learnt from the Prophet (S.A.W.) early life\nappreciate the qualities of the Prophet (S.A.W.) in shaping the life of a Muslim', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:51', '2026-08-01 00:02:51'),
(4687, 44, 2, 89, 'Religious Education', 89, 737, 2763, NULL, NULL, 8, NULL, 'Religious Education: Islamic Festivals - Milad un – Nabii (IRE)', 'Islamic Festivals', 36, 'Islamic Festivals', 'Milad un – Nabii', 'name the date, day and month the Prophet was born\noutline the activities that take place during the Milad un-Nabii c for remembrance of the Prophet (S.A.W.)’s life\nappreciate the siirah of the prophet (S.A.W.) as the foundation of Islamic History', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:51', '2026-08-01 00:02:51'),
