(4947, 44, 4, 105, 'Social Studies', 105, 1014, 4110, NULL, NULL, 8, NULL, 'Social Studies: Social Studies and Career Development - Pre-career Support systems (Psychosocial, social, mentorship/coach ing, spiritual, career support system)', 'Social Studies and Career Development', 2, 'Social Studies and Career Development', 'Pre-career Support systems (Psychosocial, social, mentorship/coach ing, spiritual, career support system)', 'explore and use support systems for pre-career and other needs\nanalyze challenges arising from existing support systems for pre- career and other needs\ndesign solutions to challenges arising from support systems\nexplain the significance of pre-career mapping for individual growth\nappreciate the value of the pre-career support systems', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(4948, 44, 4, 105, 'Social Studies', 105, 1015, 4111, NULL, NULL, 8, NULL, 'Social Studies: Community Service Learning - Community Service Learning Project', 'Community Service Learning', 3, 'Community Service Learning', 'Community Service Learning Project', 'identify a problem in the community\ndesign a solution to the identified problem\nplan to solve the identified problem in the community\nimplement the plan to solve the problem\nwrite a report on the concluded project\nappreciate teamwork in addressing community problems', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
