(4996, 44, 6, 86, 'Indigenous Language', 86, 636, 2404, NULL, NULL, 8, NULL, 'Indigenous Language: Writing - Handwriting- Letters of the Alphabet', 'Writing', 11, 'Writing', 'Handwriting- Letters of the Alphabet', 'outline the letters of the language alphabet\ncopy names of things found at home in upper case and lower case\ndevelop an interest in writing using letters of the language alphabet', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(4997, 44, 6, 86, 'Indigenous Language', 86, 636, 2405, NULL, NULL, 8, NULL, 'Indigenous Language: Writing - Handwriting – Neatness and Legibility', 'Writing', 12, 'Writing', 'Handwriting – Neatness and Legibility', 'outline items in the school neatly and legibly\nre-write simple words related to school\nenjoy writing words using acquired language neatly and legibly', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(4998, 44, 6, 86, 'Indigenous Language', 86, 636, 2406, NULL, NULL, 8, NULL, 'Indigenous Language: Writing - Spelling', 'Writing', 13, 'Writing', 'Spelling', 'write simple words related to good manners accurately\nuse simple words related to good manners to make simple sentences\nenjoy writing texts accurately for communication', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(4999, 44, 6, 86, 'Indigenous Language', 86, 636, 2407, NULL, NULL, 8, NULL, 'Indigenous Language: Writing - Writing Words', 'Writing', 14, 'Writing', 'Writing Words', 'combine letters to form words related to the theme\nwrite simple words related to personal hygiene for expression\nenjoy creating texts on personal hygiene for information', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(5000, 44, 6, 85, 'Kiswahili', 85, 630, 2362, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Maamkuzi na Maagano', 'Kusikiliza na Kuzungumza', 1, 'Kusikiliza na Kuzungumza', 'Maamkuzi na Maagano', 'kutambua maneno yanayotumiwa katika maamkuzi na maagano\nkuamkua na kuitikia maamkuzi na maagano ipasavyo ili kufanikisha mawasiliano\nkuchangamkia maamkuzi na maagano katika maisha ya kila siku', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(5001, 44, 6, 85, 'Kiswahili', 85, 630, 2363, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora Sauti: (/m/, /a/, /u/, /k/, /t/ /l/)', 'Kusikiliza na Kuzungumza', 2, 'Kusikiliza na Kuzungumza', 'Matamshi Bora Sauti: (/m/, /a/, /u/, /k/, /t/ /l/)', 'kutambua sauti lengwa katika matini\nkutamka sauti lengwa ipasavyo ili kuimarisha mazungumzo\nkutamka silabi za sauti lengwa ipasavyo\nkutamka ipasavyo maneno yenye silabi za sauti lengwa\nkuchangamkia nafasi ya matamshi bora katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(5002, 44, 6, 85, 'Kiswahili', 85, 630, 2364, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Maneno ya Adabu na Heshima', 'Kusikiliza na Kuzungumza', 3, 'Kusikiliza na Kuzungumza', 'Maneno ya Adabu na Heshima', 'kutambua maneno ya adabu na heshima yanayotumiwa katika jamii\nkutumia ipasavyo maneno ya adabu na heshima katika mawasiliano\nkuthamini matumizi ya maneno ya adabu na heshima katika mawasiliano ya kila siku', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(5003, 44, 6, 85, 'Kiswahili', 85, 630, 2365, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora Sauti: (/n/, /o/, /w/, /e/, /i/, /h/)', 'Kusikiliza na Kuzungumza', 4, 'Kusikiliza na Kuzungumza', 'Matamshi Bora Sauti: (/n/, /o/, /w/, /e/, /i/, /h/)', 'kutambua sauti lengwa katika matini\nkutamka sauti lengwa ipasavyo ili kuimarisha mazungumzo\nkutamka silabi za sauti lengwa ipasavyo\nkutamka ipasavyo maneno yenye silabi za sauti lengwa\nkuchangamkia nafasi ya matamshi bora katika mawasiliano. •', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(5004, 44, 6, 85, 'Kiswahili', 85, 630, 2366, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Ufahamu wa Kusikiliza Kifungu', 'Kusikiliza na Kuzungumza', 5, 'Kusikiliza na Kuzungumza', 'Ufahamu wa Kusikiliza Kifungu', 'kutambua msamiati wa suala lengwa katika kifungu\nkutunga sentensi sahihi akitumia msamiati uliotumiwa\nkusikiliza kifungu anachosomewa cha maneno kati ya 15-20 na kupata ujumbe\nkujibu maswali kuhusu hadithi aliyosikiliza\nkuchangamkia kusikiliza kifungu ili kujenga ari ya kusoma', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(5005, 44, 6, 85, 'Kiswahili', 85, 630, 2367, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora Sauti: (/s/, /b/, /y/, /z/, /g/, /d/)', 'Kusikiliza na Kuzungumza', 6, 'Kusikiliza na Kuzungumza', 'Matamshi Bora Sauti: (/s/, /b/, /y/, /z/, /g/, /d/)', 'kutambua sauti lengwa katika kadi maneno\nkutamka sauti lengwa ipasavyo ili kuimarisha mazungumzo\nkutamka silabi za sauti lengwa ipasavyo\nkutamka ipasavyo maneno yenye silabi za sauti lengwa\nkuchangamkia nafasi ya matamshi bora katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(5006, 44, 6, 85, 'Kiswahili', 85, 630, 2368, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi bora Sauti: (/j/, /r/, /p/, /f/, /v/, /sh/)', 'Kusikiliza na Kuzungumza', 7, 'Kusikiliza na Kuzungumza', 'Matamshi bora Sauti: (/j/, /r/, /p/, /f/, /v/, /sh/)', 'kutambua sauti lengwa katika kadi maneno\nkutamka sauti lengwa ipasavyo ili kuimarisha mazungumzo\nkutamka silabi za sauti sauti lengwa ipasavyo\nkutamka ipasavyo maneno yenye silabi za sauti lengwa\nkuchangamkia nafasi ya matamshi bora katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(5007, 44, 6, 85, 'Kiswahili', 85, 630, 2369, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Mazungumzo', 'Kusikiliza na Kuzungumza', 8, 'Kusikiliza na Kuzungumza', 'Mazungumzo', 'kutambua suala lengwa ili azungumze kulihusu\nkuzungumza kuhusu suala lengwa akizingatia matamshi bora na ishara zifaazo\nkujieleza kwa ujasiri, kasi ifaayo na sauti inayosikika\nkuchangamkia mazungumzo na matamshi bora katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(5008, 44, 6, 85, 'Kiswahili', 85, 630, 2370, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora Sauti: (/ny/, /dh/, /th/, /ch/, /gh/, /ng/, /ng’/)', 'Kusikiliza na Kuzungumza', 9, 'Kusikiliza na Kuzungumza', 'Matamshi Bora Sauti: (/ny/, /dh/, /th/, /ch/, /gh/, /ng/, /ng’/)', 'kutambua sauti lengwa katika kadi maneno\nkutamka sauti lengwa ipasavyo ili kuimarisha mazungumzo\nkutamka silabi za sauti lengwa ipasavyo\nkutamka ipasavyo maneno yenye silabi za sauti lengwa\nkuchangamkia nafasi ya matamshi bora katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52'),
(5009, 44, 6, 85, 'Kiswahili', 85, 631, 2371, NULL, NULL, 8, NULL, 'Kiswahili: Kusoma - Usomaji Mwafaka', 'Kusoma', 10, 'Kusoma', 'Usomaji Mwafaka', 'kutambua namna ifaayo ya kuketi anaposoma\nkutambua jinsi ya kushika kitabu ipasavyo anaposoma\nkuelekeza macho kutoka kushoto hadi kulia na kutoka juu ya ukurasa hadi chini anaposoma\nkuonea fahari usomaji mwafaka maishani', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:52', '2026-08-01 00:02:52');
