(5141, 44, 7, 85, 'Kiswahili', 85, 672, 2503, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Maamkuzi na Maagano', 'Kusikiliza na Kuzungumza', 1, 'Kusikiliza na Kuzungumza', 'Maamkuzi na Maagano', 'kutambua maamkuzi na maagano ya nyakati za siku\nkuamkua na kuitikia maamkuzi na maagano ya nyakati za siku\nkufurahia kuamkua na kuagana ili kujenga mshikamano wa kijamii\nkutambua maamkuzi na maagano mbalimbali yatumiwayo katika jamii\nkutumia ipasavyo maamkuzi na maagano mbalimbali yatumiwayo katika jamii\nkuthamini matumizi ya maamkuzi na maagano katika mawasiliano ya kila siku', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:54', '2026-08-01 00:02:54'),
(5142, 44, 7, 85, 'Kiswahili', 85, 672, 2504, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora. Sauti: /p/, /f/, /v/', 'Kusikiliza na Kuzungumza', 2, 'Kusikiliza na Kuzungumza', 'Matamshi Bora. Sauti: /p/, /f/, /v/', 'kutambua silabi za sauti lengwa katika maandishi\nkutamka ipasavyo silabi za sauti lengwa katika maandishi\nkutamka maneno mepesi yanayotokana na sauti lengwa katika maandishi\nkusoma ipasavyo sentensi nyepesi zenye sauti lengwa kwa matamshi bora\nkuchangamkia usomaji bora wa maneno yanayotumia sauti', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:54', '2026-08-01 00:02:54'),
(5143, 44, 7, 85, 'Kiswahili', 85, 672, 2505, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Maneno ya Heshima na Adabu Hodi, karibu, tafadhali, ninaomba, nisamehe na nashukuru', 'Kusikiliza na Kuzungumza', 3, 'Kusikiliza na Kuzungumza', 'Maneno ya Heshima na Adabu Hodi, karibu, tafadhali, ninaomba, nisamehe na nashukuru', 'kutambua maneno ya heshima na adabu yanayotumiwa katika jamii\nkutumia ipasavyo maneno ya heshima na adabu katika mawasiliano akiambatanisha na hisia zifaazo\nkuthamini matumizi ya maneno ya heshima na adabu katika mawasiliano ya kila siku', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:54', '2026-08-01 00:02:54'),
(5144, 44, 7, 85, 'Kiswahili', 85, 672, 2506, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora Sauti; /ch/ na /dh/', 'Kusikiliza na Kuzungumza', 4, 'Kusikiliza na Kuzungumza', 'Matamshi Bora Sauti; /ch/ na /dh/', 'kutambua silabi za sauti lengwa katika maneno\nkutamka maneno yenye silabi za sauti lengwa kwa ufasaha\nkusoma kifungu kifupi chenye maneno ya sauti lengwa akizingatia matamshi bora\nkufurahia matamshi bora katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:54', '2026-08-01 00:02:54'),
(5145, 44, 7, 85, 'Kiswahili', 85, 672, 2507, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Ufahamu wa Kusikiliza Hadithi', 'Kusikiliza na Kuzungumza', 5, 'Kusikiliza na Kuzungumza', 'Ufahamu wa Kusikiliza Hadithi', 'kutambua picha kuhusu suala lengwa\nkutambua msamiati wa suala lengwa uliotumiwa katika hadithi aliyoisikiliza\nkujibu maswali kuhusu hadithi aliyoisikiliza\nkueleza ujumbe wa hadithi aliyoisikiliza\nkufurahia ufahamu wa kusikiliza', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:54', '2026-08-01 00:02:54'),
(5146, 44, 7, 85, 'Kiswahili', 85, 672, 2508, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora: Sauti:/ny/ na /ng/', 'Kusikiliza na Kuzungumza', 6, 'Kusikiliza na Kuzungumza', 'Matamshi Bora: Sauti:/ny/ na /ng/', 'kutambua silabi za sauti lengwa ipasavyo katika maneno na sentensi\nkutamka maneno na sentensi zenye silabi za sauti lengwa kwa ufasaha\nkufurahia matamshi bora katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:54', '2026-08-01 00:02:54'),
(5147, 44, 7, 85, 'Kiswahili', 85, 672, 2509, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora Sauti: /sh/, /th/', 'Kusikiliza na Kuzungumza', 7, 'Kusikiliza na Kuzungumza', 'Matamshi Bora Sauti: /sh/, /th/', 'kutambua maneno na sentensi zenye sauti lengwa\nkutamka maneno na sentensi za sauti lengwa kwa ufasaha\nkufurahia matamshi bora katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:54', '2026-08-01 00:02:54'),
(5148, 44, 7, 85, 'Kiswahili', 85, 672, 2510, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Mazungumzo ya papo kwa hapo', 'Kusikiliza na Kuzungumza', 8, 'Kusikiliza na Kuzungumza', 'Mazungumzo ya papo kwa hapo', 'kuonyesha ufahamu wa suala linalozungumziwa\nkuzingatia matamshi bora anapozungumza\nkujieleza kwa ufasaha wakati wa kuzungumza, kutumia viziada lugha ipasavyo wakati wa kuzungumza\nkufurahia kutoa mazungumzo ya papo kwa hapo ili kujenga ufasaha wa kuzungumza', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:54', '2026-08-01 00:02:54'),
(5149, 44, 7, 85, 'Kiswahili', 85, 672, 2511, NULL, NULL, 8, NULL, 'Kiswahili: Kusikiliza na Kuzungumza - Matamshi Bora Alfabeti ya Kiswahili', 'Kusikiliza na Kuzungumza', 9, 'Kusikiliza na Kuzungumza', 'Matamshi Bora Alfabeti ya Kiswahili', 'kutambua sauti mbalimbali za alfabeti ya Kiswahili\nkutamka maneno yenye silabi za sauti mbalimbali za Kiswahili kwa ufasaha\nkufurahia matamshi bora katika mawasiliano', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:54', '2026-08-01 00:02:54'),
(5150, 44, 7, 85, 'Kiswahili', 85, 673, 2512, NULL, NULL, 8, NULL, 'Kiswahili: Kusoma - Kusoma Ufahamu Kusoma kifungu', 'Kusoma', 10, 'Kusoma', 'Kusoma Ufahamu Kusoma kifungu', 'kutambua msamiati kuhusu suala lengwa katika kifungu chepesi cha ufahamu\nkutabiri yatakayotokea katika kifungu chepesi cha ufahamu kwa kuzingatia picha\nkueleza ujumbe wa kifungu chepesi cha ufahamu\nkueleza mafunzo yanayotokana na kifungu chepesi cha ufahamu\nkuchangamkia kusoma vifungu vya ufahamu ili kuimarisha stadi ya kusoma', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:54', '2026-08-01 00:02:54'),
