(5739, 44, 9, 96, 'Science & Technology', 96, 843, 3240, NULL, NULL, 8, NULL, 'Science & Technology: Living Things and their Environment - Classification of Plants', 'Living Things and their Environment', 1, 'Living Things and their Environment', 'Classification of Plants', 'classify plants into flowering and non- flowering\ndescribe functions of parts of a flower\noutline the importance of flowers in nature\nappreciate the importance of flowers in nature', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5740, 44, 9, 96, 'Science & Technology', 96, 843, 3241, NULL, NULL, 8, NULL, 'Science & Technology: Living Things and their Environment - The Human Breathing System', 'Living Things and their Environment', 2, 'Living Things and their Environment', 'The Human Breathing System', 'identify the main parts of the human breathing system\ndescribe the functions of parts of the human breathing system\ncoutline the symptoms and prevention measures for common conditions and diseases of the breathing system', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5741, 44, 9, 96, 'Science & Technology', 96, 844, 3242, NULL, NULL, 8, NULL, 'Science & Technology: Matter - Mixtures', 'Matter', 3, 'Matter', 'Mixtures', 'classify mixtures as homogeneous or heterogeneous\napply appropriate methods to separate heterogeneous mixtures\noutline the applications of separating mixtures in day-to-day life\nappreciate different methods of separating mixtures in day-to-day life', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
