(5824, 44, 10, 101, 'English', 101, 897, 3502, NULL, NULL, 8, NULL, 'English: Reading - Intensive Reading: Visuals', 'Reading', 28, 'Reading', 'Intensive Reading: Visuals', 'identify types of information conveyed by visuals for comprehension\ninterpret visuals for information\nappreciate the importance of visual, interpretation skills in different texts', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5825, 44, 10, 101, 'English', 101, 897, 3503, NULL, NULL, 8, NULL, 'English: Reading - Intensive Reading: Characters in class readers', 'Reading', 29, 'Reading', 'Intensive Reading: Characters in class readers', 'identify minor characters in a class reader\nDiscuss the relationships between different minor characters in the class reader\nappreciate the place of minor characters in the class reader', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5826, 44, 10, 101, 'English', 101, 897, 3504, NULL, NULL, 8, NULL, 'English: Reading - Extensive Reading: Grade appropriate fiction materials', 'Reading', 30, 'Reading', 'Extensive Reading: Grade appropriate fiction materials', 'select a variety of fictional texts for extensive reading\nread fictional texts for information and enjoyment\nappreciate the importance of fiction in life', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5827, 44, 10, 101, 'English', 101, 897, 3505, NULL, NULL, 8, NULL, 'English: Reading - Study Skills', 'Reading', 31, 'Reading', 'Study Skills', 'identify the main and supporting points in texts\nmake notes from varieties of written texts\nrelate note making to effective reading', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5828, 44, 10, 101, 'English', 101, 897, 3506, NULL, NULL, 8, NULL, 'English: Reading - Intensive Reading: Characters and their traits', 'Reading', 32, 'Reading', 'Intensive Reading: Characters and their traits', 'identify characters in monster narratives, (\nexplain traits of characters in given monster narratives, (\nrelate monster narratives to real life situations, (\nappreciate the importance of monster narratives in life', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5829, 44, 10, 101, 'English', 101, 897, 3507, NULL, NULL, 8, NULL, 'English: Reading - Extensive Reading: Non-Fiction materials', 'Reading', 33, 'Reading', 'Extensive Reading: Non-Fiction materials', 'identify print or electronic non-fiction materials that are interesting to read\nread a variety of grade appropriate non-fiction materials independently for lifelong learning\nrecommend to peers suitable non- fiction materials to read for information\nacknowledge the importance of reading for enjoyment and general understanding', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5830, 44, 10, 101, 'English', 101, 897, 3508, NULL, NULL, 8, NULL, 'English: Reading - Intensive Reading- Comprehension', 'Reading', 34, 'Reading', 'Intensive Reading- Comprehension', 'identify main ideas in a text\nuse contextual clues to infer the meaning of words in a text\ndescribe characters, ideas or events in a text\nsummarise information from a short text\nappreciate the importance of reading comprehension in lifelong learning', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5831, 44, 10, 101, 'English', 101, 897, 3509, NULL, NULL, 8, NULL, 'English: Reading - Class Reader: Main Ideas', 'Reading', 35, 'Reading', 'Class Reader: Main Ideas', 'identify the main ideas in the section read in the text\ndiscuss the lessons learnt from the text\nrelate the lessons learnt to real life experiences\nappreciate the role of literature in fostering critical thinking', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5832, 44, 10, 101, 'English', 101, 897, 3510, NULL, NULL, 8, NULL, 'English: Reading - Intensive Reading: Comprehension Strategies', 'Reading', 36, 'Reading', 'Intensive Reading: Comprehension Strategies', 'identify key ideas from a passage\nsummarise key ideas from a passage\ncreate mental images from the events in a passage\ndeduce the meaning of words from context\nrespond to factual and inferential questions, correctly from the passage\nacknowledge the importance of comprehension strategies in effective reading', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
(5833, 44, 10, 101, 'English', 101, 897, 3511, NULL, NULL, 8, NULL, 'English: Reading - Oral Literature: Praise Songs', 'Reading', 37, 'Reading', 'Oral Literature: Praise Songs', 'identify the purpose and occasions for which praise songs are performed\ndiscuss the relationship between the singer and the person being praised in praise songs\nperform praise songs sang in their immediate environment\ncollaborate with peers in performing the praise songs\nappreciate the purpose of praise songs in communication\nas brought out in the praise song(\n1. Why do we sing? 2. What kind of people are praised in songs? 3. How do songs portray people’s character? 4. What are the qualities of a good singer?', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57');
INSERT IGNORE INTO `schemes_of_work` (`id`, `teacher_id`, `class_id`, `subject_id`, `subject_name`, `learning_area_id`, `strand_id`, `sub_strand_id`, `coverage_id`, `academic_year_id`, `term_id`, `term_number`, `title`, `description`, `week_number`, `strand`, `sub_strand`, `learning_outcomes`, `key_vocabulary`, `resources`, `activities`, `assessment_methods`, `status`, `approved_by`, `approved_at`, `rejection_reason`, `file_path`, `created_at`, `updated_at`) VALUES
(5834, 44, 10, 101, 'English', 101, 897, 3512, NULL, NULL, 8, NULL, 'English: Reading - Study Skills: Summarising', 'Reading', 38, 'Reading', 'Study Skills: Summarising', 'identify the main ideas in texts\nwrite a summary of ideas from varied texts\nappreciate the importance of summarising information in a given context', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:02:57', '2026-08-01 00:02:57'),
