INSERT IGNORE INTO `schemes_of_work` (`id`, `teacher_id`, `class_id`, `subject_id`, `subject_name`, `learning_area_id`, `strand_id`, `sub_strand_id`, `coverage_id`, `academic_year_id`, `term_id`, `term_number`, `title`, `description`, `week_number`, `strand`, `sub_strand`, `learning_outcomes`, `key_vocabulary`, `resources`, `activities`, `assessment_methods`, `status`, `approved_by`, `approved_at`, `rejection_reason`, `file_path`, `created_at`, `updated_at`) VALUES
(6560, 44, 14, 87, 'Mathematics', 87, 637, 2408, NULL, NULL, 8, NULL, 'Mathematics: Numbers - Pre-number activities', 'Numbers', 1, 'Numbers', 'Pre-number activities', 'sort objects according to similar attributes in different situations\nmatch objects with similar attributes in the environment\norder objects according to given criteria in different situations\ncreate patterns of different sizes and shapes using real objects\nappreciate the use of sorting and grouping items in day-to-day activities', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6561, 44, 14, 87, 'Mathematics', 87, 637, 2409, NULL, NULL, 8, NULL, 'Mathematics: Numbers - Whole Numbers', 'Numbers', 2, 'Numbers', 'Whole Numbers', 'count numbers forward up to 50\ncount numbers backward from 30\nrepresent numbers 1 to 30 using concrete objects\nread and write numbers 1 to 50 in symbols\nread and write numbers 1 to 10 in words\nidentify missing numbers in number patterns up to 20\nappreciate number patterns by creating', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6562, 44, 14, 87, 'Mathematics', 87, 637, 2410, NULL, NULL, 8, NULL, 'Mathematics: Numbers - Addition', 'Numbers', 3, 'Numbers', 'Addition', 'model addition as putting objects together\nuse \' +\' and \' =\' signs in writing addition statements\nadd 2 single-digit numbers in different situations\nadd 3 single-digit numbers in different contexts\nadd a 2-digit number to a 1-digit number without regrouping with sum not exceeding 50\nwork out missing numbers in patterns involving the addition of whole numbers up to 50\nplay games involving addition using digital devices or other resources. numbers up to 50, ● play games involving addition using digital devices and other resources', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6563, 44, 14, 87, 'Mathematics', 87, 637, 2411, NULL, NULL, 8, NULL, 'Mathematics: Numbers - Subtraction', 'Numbers', 4, 'Numbers', 'Subtraction', 'model subtraction as', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6564, 44, 14, 87, 'Mathematics', 87, 638, 2412, NULL, NULL, 8, NULL, 'Mathematics: Measurement - Length', 'Measurement', 5, 'Measurement', 'Length', 'collect objects of different lengths from the immediate environment\ncompare the length of objects using longer than, shorter than, and same as\nmeasure length using arbitrary units\nappreciate measuring length using arbitrary units', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6565, 44, 14, 87, 'Mathematics', 87, 638, 2413, NULL, NULL, 8, NULL, 'Mathematics: Measurement - Mass', 'Measurement', 6, 'Measurement', 'Mass', 'collect objects with different masses from the immediate environment\ncompare the mass of two objects using heavier than, lighter than, or same as\nmeasure mass using arbitrary units\nappreciate measuring mass using arbitrary units in the environment', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6566, 44, 14, 87, 'Mathematics', 87, 638, 2414, NULL, NULL, 8, NULL, 'Mathematics: Measurement - Capacity', 'Measurement', 7, 'Measurement', 'Capacity', 'collect containers of different capacities from the immediate environment\ncompare the capacity of two containers using more than, less than, and same as\nmeasure capacity using arbitrary units\nre-use empty containers of different capacities to keep items', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6567, 44, 14, 87, 'Mathematics', 87, 638, 2415, NULL, NULL, 8, NULL, 'Mathematics: Measurement - Time', 'Measurement', 8, 'Measurement', 'Time', 'identify days of the week\nrelate days of the week to various activities\nidentify months of the year\nappreciate activities that are done on different days of the week', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6568, 44, 14, 87, 'Mathematics', 87, 638, 2416, NULL, NULL, 8, NULL, 'Mathematics: Measurement - Money', 'Measurement', 9, 'Measurement', 'Money', 'identify Kenyan currency coins\nidentify the sh.50 Kenyan currency note\ncount Kenyan currency coins one at a time\nuse money to buy up to 2 items without balance\nappreciate the use of money in buying items from shops', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6569, 44, 14, 87, 'Mathematics', 87, 639, 2417, NULL, NULL, 8, NULL, 'Mathematics: Geometry - Lines', 'Geometry', 10, 'Geometry', 'Lines', 'identify straight lines in different situations\ndraw straight lines on different surfaces\nidentify curved lines in different situations\ndraw curved lines on different surfaces\nrecognise straight and curved lines from real objects in the environment', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6570, 44, 14, 87, 'Mathematics', 87, 639, 2418, NULL, NULL, 8, NULL, 'Mathematics: Geometry - Shapes', 'Geometry', 11, 'Geometry', 'Shapes', 'identify rectangles, triangles, and circles in objects from the environment\nmake patterns involving rectangles, triangles, circles, and ovals\nappreciate the beauty of patterns in different fabrics', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:01', '2026-08-01 00:03:01'),
(6571, 44, 14, 90, 'Movement & Creative Activities', 90, 665, 2478, NULL, NULL, 8, NULL, 'Movement & Creative Activities: Creating and Executing - Jumping', 'Creating and Executing', 1, 'Creating and Executing', 'Jumping', 'identify different ways of jumping for body agility\nimprovise objects to be used for jumping\njump in different ways for coordination\nsing songs while jumping for fun\nappreciate jumping for enjoyment while observing safety', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:02', '2026-08-01 00:03:02'),
(6572, 44, 14, 90, 'Movement & Creative Activities', 90, 665, 2479, NULL, NULL, 8, NULL, 'Movement & Creative Activities: Creating and Executing - Rhythm', 'Creating and Executing', 2, 'Creating and Executing', 'Rhythm', 'identify items that maintain a steady pulse for beat articulation\nplay a steady beat on a percussion instrument while singing\ncreate a rhythmic accompaniment to a song using body percussion\nappreciate the use of percussions in creating rhythm', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:02', '2026-08-01 00:03:02'),
