(6574, 44, 14, 90, 'Movement & Creative Activities', 90, 665, 2481, NULL, NULL, 8, NULL, 'Movement & Creative Activities: Creating and Executing - Stretching', 'Creating and Executing', 4, 'Creating and Executing', 'Stretching', 'identify body parts involved in stretching\nperform stretching in different directions for flexibility\nenjoy stretching in different directions for body fitness', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:02', '2026-08-01 00:03:02'),
(6575, 44, 14, 90, 'Movement & Creative Activities', 90, 665, 2482, NULL, NULL, 8, NULL, 'Movement & Creative Activities: Creating and Executing - Painting and Colouring', 'Creating and Executing', 5, 'Creating and Executing', 'Painting and Colouring', 'identify materials and tools for painting and colouring\ncolour a picture to immitate the environment\npaint shapes using a brush\npaint using fingers on a surface\npaint using a sponge on a surface\nenjoy painting and colouring as a form of expression', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:02', '2026-08-01 00:03:02'),
(6576, 44, 14, 90, 'Movement & Creative Activities', 90, 665, 2483, NULL, NULL, 8, NULL, 'Movement & Creative Activities: Creating and Executing - Melody (14 le ssons)', 'Creating and Executing', 6, 'Creating and Executing', 'Melody (14 le ssons)', 'identify sounds as melodic or non-melodic for aural discrimination\naurally recognise like and unlike passages in short melodies\necho simple melodic patterns by singing or humming for aural skill development\nenjoy replicating melodic passages for aural discrimination', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:02', '2026-08-01 00:03:02'),
