(6578, 44, 14, 90, 'Movement & Creative Activities', 90, 666, 2485, NULL, NULL, 8, NULL, 'Movement & Creative Activities: Performing and Displaying - Singing Games-Kenyan Style', 'Performing and Displaying', 8, 'Performing and Displaying', 'Singing Games-Kenyan Style', 'identify props used in the performance of a singing game from a Kenyan community\nimprovise a simple prop for use in performing a singing game\nperform singing games drawn from local cultures in Kenyan for enjoyment\nenjoy performing singing games from Kenyan local cultures', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:02', '2026-08-01 00:03:02'),
(6579, 44, 14, 90, 'Movement & Creative Activities', 90, 666, 2486, NULL, NULL, 8, NULL, 'Movement & Creative Activities: Performing and Displaying - Throwing and Catching', 'Performing and Displaying', 9, 'Performing and Displaying', 'Throwing and Catching', 'identify materials used to improvise a ball\nimprovise a ball from locally available materials\nperform throwing and catching activities for skill acquisition\nappreciate throwing and catching activities for enjoyment', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:02', '2026-08-01 00:03:02'),
(6580, 44, 14, 90, 'Movement & Creative Activities', 90, 666, 2487, NULL, NULL, 8, NULL, 'Movement & Creative Activities: Performing and Displaying - Paper Craft', 'Performing and Displaying', 10, 'Performing and Displaying', 'Paper Craft', 'identify it ems made using paper craft\nmake paper items using the pleating technique\nmake paper items using the folding technique\nplay using the pa per items for enjoyment', NULL, NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, '2026-08-01 00:03:02', '2026-08-01 00:03:02'),
