INSERT IGNORE INTO `school_content` (`id`, `content_key`, `content_value`, `updated_at`) VALUES
(1, 'mission', 'To provide a nurturing, inclusive, and academically rigorous environment that develops confident, virtuous, and globally-competitive learners through the Kenya Competency-Based Curriculum.', '2026-04-27 06:18:19'),
(2, 'vision', 'To be the most preferred school of excellence in the East African region, producing well-rounded, morally upright, and intellectually superior graduates.', '2026-04-27 06:18:19'),
(3, 'about_intro', 'Founded with a vision to provide holistic education, Kingsway Preparatory School has grown into one of the leading schools in the Rift Valley region. We nurture academic excellence, strong values, and practical life skills in every learner from Pre-Primary through Junior Secondary School.', '2026-04-27 06:18:19'),
(4, 'hero_subtitle', 'Kingsway Preparatory School provides world-class education combining the Kenya Competency-Based Curriculum with holistic character development, sports, and co-curricular excellence — in the heart of Londiani, Kenya.', '2026-04-27 06:18:19');
INSERT IGNORE INTO `school_events` (`id`, `title`, `description`, `event_date`, `event_time`, `end_date`, `location`, `category`, `status`, `created_at`, `updated_at`) VALUES
(1, 'End of Term 2 Examinations Begin', 'All classes from Grade 1 through Grade 9 sit their end-of-term written examinations. Examination timetables have been distributed to all learners. Students should arrive by 7:15 AM with all stationery.', '2026-05-11', '07:30:00', NULL, 'All Classrooms', 'Academic', 'upcoming', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(2, 'Term 2 Parent-Teacher Feedback Day', 'Parents and guardians are invited to meet class teachers to review Term 2 academic results and set Term 3 targets. Report books will be handed directly to parents. Tea and refreshments provided by the PTA.', '2026-05-18', '08:00:00', NULL, 'All Classrooms & School Hall', 'Meeting', 'upcoming', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(3, 'Annual Prize-Giving & Awards Ceremony', 'Celebrating excellence in academics, sports, arts, and character development. Parents and guardians warmly welcome. Smart casual dress code for students. Guest speaker to be announced.', '2026-05-25', '10:00:00', NULL, 'School Assembly Ground', 'Ceremony', 'upcoming', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(4, 'Term 2 Closing Day', 'Last day of Term 2. Boarding students to be collected by parents or guardians by 4:00 PM. All fees must be cleared before report books are released.', '2026-06-01', '12:00:00', NULL, 'School Campus', 'Academic', 'upcoming', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(5, 'Term 3 Opening Day', 'Students report back for Term 3. Day scholars arrive by 7:30 AM. Boarding students to report between 2:00 PM and 6:00 PM with all requirements. New students report with parents to the admissions office.', '2026-06-15', '07:30:00', NULL, 'School Gates & Dormitories', 'Academic', 'upcoming', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(6, 'Sub-County Athletics Championship', 'Kingsway hosts the Annual Sub-County Inter-Schools Athletics Championship. Schools across the sub-county compete in track and field events. Spectators are welcome.', '2026-06-29', '08:00:00', NULL, 'School Sports Ground', 'Sports', 'upcoming', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(7, 'Grade 9 KJSEA Mock Examination', 'A full simulation of the Kenya Junior School Education Assessment for all Grade 9 learners. Results guide final revision strategies for the main national assessment.', '2026-07-13', '08:00:00', NULL, 'Grade 9 Classrooms', 'Academic', 'upcoming', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(8, 'Annual Cultural Day & Heritage Festival', 'Students, teachers and parents celebrate Kenya\'s rich cultural diversity. Students come dressed in traditional attire, perform cultural dances, songs, and present traditional foods. All families welcome.', '2026-07-27', '09:00:00', NULL, 'School Assembly Ground', 'Cultural', 'upcoming', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(9, 'PTA Annual General Meeting', 'The Parent-Teacher Association holds its AGM to review school progress, elect new committee members, and plan fundraising activities for the year.', '2026-08-10', '10:00:00', NULL, 'School Hall', 'Meeting', 'upcoming', '2026-04-27 06:13:56', '2026-04-27 06:13:56'),
(10, 'End of Year Prize-Giving Ceremony', 'The most prestigious event in the school calendar — celebrating academic excellence, sporting achievement, character awards, and Grade 9 leavers. All parents and guardians warmly invited.', '2026-09-14', '10:00:00', NULL, 'School Assembly Ground', 'Ceremony', 'upcoming', '2026-04-27 06:13:56', '2026-04-27 06:13:56');
INSERT IGNORE INTO `school_facilities` (`id`, `icon`, `name`, `description`, `display_order`, `is_active`) VALUES
(1, 'bi-building', 'Modern Classrooms', '32 well-ventilated, fully-furnished classrooms equipped for CBC project-based learning.', 10, 1),
(2, 'bi-laptop', 'ICT Computer Lab', '40-station computer laboratory with high-speed fibre internet and CBC educational software.', 20, 1),
(3, 'bi-book', 'School Library', 'Over 12,000 books including CBC-aligned reference materials, fiction, and digital resource tablets.', 30, 1),
(4, 'bi-heart-pulse', 'Sick Bay', 'Fully equipped sick bay managed by a qualified residential nurse available 24/7 for boarding students.', 40, 1),
(5, 'bi-house-door', 'Dormitories', 'Separate boys and girls dormitories with houseparents on duty around the clock.', 50, 1),
(6, 'bi-cup-hot', 'Dining Hall', 'Spacious dining hall serving three balanced, nutritious meals daily for all boarding students.', 60, 1),
(7, 'bi-flag', 'Sports Grounds', 'Full-size football pitch, basketball and netball courts, and athletics track.', 70, 1),
(8, 'bi-music-note', 'Music & Arts Room', 'Dedicated music room with instruments for lessons, choir practice, and the drama club.', 80, 1),
(9, 'bi-flask', 'Science Laboratory', 'Equipped laboratory for Grade 7–9 integrated science practicals and experiments.', 90, 1),
(10, 'bi-wifi', 'Smart Classrooms', 'Interactive smart boards and projectors integrated into the Grade 6–9 classroom experience.', 100, 1),
(11, 'bi-person-hearts', 'Counselling Suite', 'Private counselling rooms for student welfare, peer mentoring, and pastoral care sessions.', 110, 1),
(12, 'bi-shop', 'School Canteen', 'Tuck shop stocking approved snacks and scholastic materials. Cashless payment system for boarders.', 120, 1);
INSERT IGNORE INTO `school_history` (`id`, `year`, `event_title`, `description`, `display_order`) VALUES
(1, '2005', 'Foundation', 'Kingsway Preparatory School was founded by a group of visionary educators committed to quality education in Londiani. The school started with 3 streams and 120 pupils.', 10),
(2, '2010', 'Growth & Recognition', 'Enrolment surpassed 400 students. The school received its first regional award for academic excellence. New classrooms and a modern library were constructed.', 20),
(3, '2015', 'Boarding Programme', 'Introduction of the full boarding programme, enabling students from across the region to benefit from Kingsway\'s quality education. Dormitory facilities expanded.', 30),
(4, '2019', 'CBC Transition', 'Seamless transition to Kenya\'s Competency-Based Curriculum. Teacher training and infrastructure upgrades positioned Kingsway as a model CBC school in the Rift Valley region.', 40),
(5, '2022', 'Digital Transformation', 'Launch of the new 40-workstation ICT Computer Lab. Introduction of smart classrooms and the school management ERP system for modern operations.', 50),
(6, '2026', 'Today', 'Over 1,200 students enrolled, 80+ qualified staff, and a track record of 98% KJSEA pass rates. Kingsway continues to grow in excellence, character, and faith.', 60);
