(4, 'Junior Secondary', 'Grade 7–9 (Ages 12–14)', 'bi-mortarboard-fill', '#e91e63', 'Integrated Science, Health Education, Pre-Technical, Business Studies, Social Studies, and KJSEA preparation.', 'academics', 40, 1),
(5, 'Boarding Programme', 'All Grades', 'bi-house-heart-fill', '#9c27b0', 'Full boarding with trained houseparents, nutritious meals, evening preps, pastoral care, and 24/7 supervision.', 'boarding', 50, 1),
(6, 'Sports & Co-Curricular', 'All Grades', 'bi-trophy-fill', '#ff9800', 'Football, Athletics, Music, Drama, Scouts, Debate, Environmental Club, and many more enrichment activities.', 'co-curricular', 60, 1),
(7, 'STEM & ICT', 'Grade 3–9', 'bi-laptop-fill', '#3f51b5', 'Computer science, robotics, coding, and digital literacy integrated across all CBC grade levels.', 'facilities', 70, 1);
